<script setup lang="ts">import {computed} from 'vue';const props=defineProps<{candles:any[]}>();const points=computed(()=>{const v=(props.candles||[]).map(x=>Number(x.close)).filter(Number.isFinite);if(v.length<2)return '';const lo=Math.min(...v),hi=Math.max(...v),span=hi-lo||1;return v.map((x,i)=>`${(i/(v.length-1))*120},${34-((x-lo)/span)*30}`).join(' ')})</script>
<template><svg class="mini-chart" viewBox="0 0 120 38" preserveAspectRatio="none"><polyline :points="points" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg></template>
